-- -------------------------------------------------------------------------
-- Change log.
-- -------------------------------------------------------------------------
CREATE TABLE sap_sfsf._change_log (
    change_log_id   BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    table_name      VARCHAR(63)  NOT NULL,
    operation       CHAR(1)      NOT NULL CHECK (operation IN ('I', 'U', 'D')),
    -- Text, not BIGINT: one log serves tables keyed by integer, bigint and
    -- composite business keys alike.
    row_key         VARCHAR(200) NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    changed_by      TEXT         NOT NULL DEFAULT current_user,
    -- Populated on delete only. Inserts and updates leave it null because
    -- the current row remains readable in the base table, and copying it
    -- would double the write volume of the busiest tables.
    old_row         JSONB
);

CREATE INDEX ix_sap_sfsf_change_log_changed_at
    ON sap_sfsf._change_log (changed_at);
CREATE INDEX ix_sap_sfsf_change_log_table
    ON sap_sfsf._change_log (table_name, changed_at);

COMMENT ON TABLE sap_sfsf._change_log IS
    'Change capture for incremental extraction. Deletes are the reason this '
    'exists: a high-water-mark read of updated_at cannot see a removed row.';

CREATE OR REPLACE FUNCTION sap_sfsf.log_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    -- TG_ARGV[0] names the key column, so one function serves every table.
    key_column TEXT := TG_ARGV[0];
    source_row JSONB;
BEGIN
    source_row := to_jsonb(COALESCE(OLD, NEW));

    INSERT INTO sap_sfsf._change_log (table_name, operation, row_key, old_row)
    VALUES (
        TG_TABLE_NAME,
        CASE TG_OP WHEN 'INSERT' THEN 'I' WHEN 'UPDATE' THEN 'U' ELSE 'D' END,
        COALESCE(source_row ->> key_column, '(unknown)'),
        CASE WHEN TG_OP = 'DELETE' THEN source_row ELSE NULL END
    );

    RETURN COALESCE(NEW, OLD);
END;
$$;

COMMENT ON FUNCTION sap_sfsf.log_change() IS
    'Generic change logger. Pass the key column name as the trigger argument.';

-- Applied to the master and financial tables, where a missed delete would
-- leave an orphan in the target model. Deliberately not applied to
-- append-only high-volume tables: the write volume would double for no
-- benefit, since nothing ever deletes from them.
CREATE TRIGGER trg_per_person_change
    AFTER INSERT OR UPDATE OR DELETE ON sap_sfsf.per_person
    FOR EACH ROW EXECUTE FUNCTION sap_sfsf.log_change('person_id_external');
CREATE TRIGGER trg_per_personal_change
    AFTER INSERT OR UPDATE OR DELETE ON sap_sfsf.per_personal
    FOR EACH ROW EXECUTE FUNCTION sap_sfsf.log_change('person_id_external');
CREATE TRIGGER trg_emp_employment_change
    AFTER INSERT OR UPDATE OR DELETE ON sap_sfsf.emp_employment
    FOR EACH ROW EXECUTE FUNCTION sap_sfsf.log_change('user_id');
CREATE TRIGGER trg_emp_job_change
    AFTER INSERT OR UPDATE OR DELETE ON sap_sfsf.emp_job
    FOR EACH ROW EXECUTE FUNCTION sap_sfsf.log_change('user_id');
CREATE TRIGGER trg_emp_compensation_change
    AFTER INSERT OR UPDATE OR DELETE ON sap_sfsf.emp_compensation
    FOR EACH ROW EXECUTE FUNCTION sap_sfsf.log_change('user_id');
CREATE TRIGGER trg_emp_time_off_change
    AFTER INSERT OR UPDATE OR DELETE ON sap_sfsf.emp_time_off
    FOR EACH ROW EXECUTE FUNCTION sap_sfsf.log_change('time_off_id');
CREATE TRIGGER trg_position_change
    AFTER INSERT OR UPDATE OR DELETE ON sap_sfsf.position
    FOR EACH ROW EXECUTE FUNCTION sap_sfsf.log_change('position_code');

-- -------------------------------------------------------------------------
-- Role separation.
--
-- The roles are created defensively because every schema grants to the same
-- three and the load order across schemas is not guaranteed.
-- -------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_app') THEN
        CREATE ROLE offball_app NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_analyst') THEN
        CREATE ROLE offball_analyst NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_ingest') THEN
        CREATE ROLE offball_ingest NOLOGIN;
    END IF;
END;
$$;

GRANT USAGE ON SCHEMA sap_sfsf TO offball_app, offball_analyst, offball_ingest;

-- The application needs everything.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA sap_sfsf
    TO offball_app;

-- Analysts and the ingestion job read.
GRANT SELECT ON ALL TABLES IN SCHEMA sap_sfsf
    TO offball_analyst, offball_ingest;

-- The satellite split only means something if the grants differ. The
-- ingestion role keeps access because the target model rejoins these
-- columns; the analyst role does not.
REVOKE SELECT ON sap_sfsf.per_person FROM offball_analyst;
REVOKE SELECT ON sap_sfsf.per_personal FROM offball_analyst;
REVOKE SELECT ON sap_sfsf.per_email FROM offball_analyst;
REVOKE SELECT ON sap_sfsf.per_phone FROM offball_analyst;
REVOKE SELECT ON sap_sfsf.per_address FROM offball_analyst;
REVOKE SELECT ON sap_sfsf.emp_compensation FROM offball_analyst;
REVOKE SELECT ON sap_sfsf.emp_pay_component FROM offball_analyst;
REVOKE SELECT ON sap_sfsf.candidate FROM offball_analyst;

COMMENT ON SCHEMA sap_sfsf IS
    'SAP SuccessFactors Employee Central -- person, employment, job, '
    'position and compensation, plus recruiting. System of record for '
    'athlete identity and workforce planning. Effective-dated throughout. '
    'Extract pattern: API incremental on last_modified_on. TIER B: '
    'abbreviated depth.';
